def raw_exercise():
    L = ['مشق', '', '۱۔ سبق کے متن کو مدِ نظر رکھ کر درست جواب پر (✓) کا نشان لگائیں تاکہ جملہ مکمل ہو جائے۔']
    for i, (q, opts, _) in enumerate(MCQ):
        L += [f'({L4[i]}) {q}'] + [f'☆ {o}' for o in opts]
    L += [f'{n}۔ {QS[k][0]}' for n, k in zip(['۲', '۳', '۴', '۵', '۶'], range(3, 8))]
    L += ['۷۔ سیاق و سباق کا حوالہ دے کر مندرجہ ذیل اقتباسات کی وضاحت کریں۔', f'(الف) {PASS_A}', f'(ب) {PASS_B}']
    L += [f'۸۔ {QS[10][0]}', f'۹۔ {QS[11][0]}', '۱۰۔ جملے درست کریں۔', '☆ نیکی کر سمندر میں ڈال۔', '☆ وہ غصے سے زرد پیلا ہو گیا۔',
          '☆ وہ بے ناغہ سکول جاتی ہے۔', '☆ میں آپ کا تابعدار ہوں۔', '☆ یہ ماہِ رمضان کا مہینہ ہے۔', '', ACTIVITY, '', TEACHER]
    return '\n'.join(L)


def fix_exercise(ex):
    ex['rawExercise'] = raw_exercise()
    ex['blanks'] = []
    ex['shortQuestions'] = [dict(question=q, answer=a) for q, a in QS]
    ex['vocabulary'] = [dict(word=w, meaning=m, sentence=s) for w, m, s in VOCAB]
    ex['grammar'] = GRAMMAR
    ex['textbookMcqs'] = [dict(question=q, options=o, correct=c, **({} if c is not None else {'note': 'No printed option matches the lesson (it says Allah).'})) for q, o, c in MCQ]
    ex.pop('mcqs', None)
    ex['activity'] = ACTIVITY.split(': ', 1)[1]
    ex['teacherInstructions'] = [TEACHER.split(': ', 1)[1]]
    ex['answerNote'] = 'SpaceBook answers (the textbook prints no answers).'
